def find_middle(s):
    if not isinstance(s, str):
        return -1
    digits = [c for c in s if c.isdigit()]
    if not digits:
        return -1
    product = eval('*'.join(digits))
    product_str = str(product)
    length = len(product_str)
    if length % 2 == 1:
        return int(product_str[length // 2])
    else:
        return int(product_str[length // 2 - 1:length // 2 + 1].lstrip('0'))
